package com.fkeytrainer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(FKeyTrainerConfig.GROUP)
public interface FKeyTrainerConfig extends Config
{
	String GROUP = "fkeytrainer";

	@ConfigItem(keyName = "enabled", name = "Enable trainer",
		description = "Block mouse actions on selected tab buttons. Set your in-game keybinds first.", position = 0)
	default boolean enabled() { return true; }

	@ConfigItem(keyName = "showFeedback", name = "Show feedback when blocked",
		description = "Briefly show a reminder to use your keybind. Never writes to chat.", position = 1)
	default boolean showFeedback() { return true; }

	@ConfigItem(keyName = "blockCombat", name = "Block Combat Options mouse clicks",
		description = "Block mouse menu actions on the Combat Options tab button, including right-click options.", position = 2)
	default boolean blockCombat() { return true; }

	@ConfigItem(keyName = "blockSkills", name = "Block Skills mouse clicks",
		description = "Block mouse menu actions on the Skills tab button, including right-click options.", position = 3)
	default boolean blockSkills() { return false; }

	@ConfigItem(keyName = "blockQuests", name = "Block Quests / Journal mouse clicks",
		description = "Block mouse menu actions on the Quests / Journal tab button, including right-click options.", position = 4)
	default boolean blockQuests() { return false; }

	@ConfigItem(keyName = "blockInventory", name = "Block Inventory mouse clicks",
		description = "Block mouse menu actions on the Inventory tab button, including right-click options.", position = 5)
	default boolean blockInventory() { return true; }

	@ConfigItem(keyName = "blockEquipment", name = "Block Worn Equipment mouse clicks",
		description = "Block mouse menu actions on the Worn Equipment tab button, including right-click options.", position = 6)
	default boolean blockEquipment() { return true; }

	@ConfigItem(keyName = "blockPrayer", name = "Block Prayer mouse clicks",
		description = "Block mouse menu actions on the Prayer tab button, including right-click options.", position = 7)
	default boolean blockPrayer() { return true; }

	@ConfigItem(keyName = "blockMagic", name = "Block Magic mouse clicks",
		description = "Block mouse menu actions on the Magic tab button, including right-click options.", position = 8)
	default boolean blockMagic() { return true; }

	@ConfigItem(keyName = "blockChannels", name = "Block Chat Channels mouse clicks",
		description = "Block mouse menu actions on the Chat Channels tab button, including right-click options.", position = 9)
	default boolean blockChannels() { return false; }

	@ConfigItem(keyName = "blockAccount", name = "Block Account Management mouse clicks",
		description = "Block mouse menu actions on the Account Management tab button, including right-click options.", position = 10)
	default boolean blockAccount() { return false; }

	@ConfigItem(keyName = "blockFriends", name = "Block Friends / Ignore mouse clicks",
		description = "Block mouse menu actions on the Friends / Ignore tab button, including right-click options.", position = 11)
	default boolean blockFriends() { return false; }

	@ConfigItem(keyName = "blockLogout", name = "Block Logout mouse clicks",
		description = "Block mouse menu actions on the Logout tab button, including right-click options.", position = 12)
	default boolean blockLogout() { return false; }

	@ConfigItem(keyName = "blockSettings", name = "Block Settings mouse clicks",
		description = "Block mouse menu actions on the Settings tab button, including right-click options.", position = 13)
	default boolean blockSettings() { return false; }

	@ConfigItem(keyName = "blockEmotes", name = "Block Emotes mouse clicks",
		description = "Block mouse menu actions on the Emotes tab button, including right-click options.", position = 14)
	default boolean blockEmotes() { return false; }

	@ConfigItem(keyName = "blockMusic", name = "Block Music mouse clicks",
		description = "Block mouse menu actions on the Music tab button, including right-click options.", position = 15)
	default boolean blockMusic() { return false; }
}

package com.fkeytrainer;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.function.LongSupplier;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

/** One replaceable reminder; no queue, chat messages, timers, or persisted history. */
class FKeyTrainerOverlay extends OverlayPanel
{
	static final long DURATION_NANOS = 1_500_000_000L;
	private final Client client;
	private final FKeyTrainerConfig config;
	private final LongSupplier clock;
	private volatile Reminder reminder;

	@Inject
	FKeyTrainerOverlay(Client client, FKeyTrainerConfig config)
	{
		this(client, config, System::nanoTime);
	}

	FKeyTrainerOverlay(Client client, FKeyTrainerConfig config, LongSupplier clock)
	{
		this.client = client;
		this.config = config;
		this.clock = clock;
		setPosition(OverlayPosition.BOTTOM_RIGHT);
		setResizable(false);
		panelComponent.setPreferredSize(new Dimension(230, 0));
	}

	void show(GameTab tab)
	{
		reminder = new Reminder(tab.displayName(), clock.getAsLong());
	}

	void clear() { reminder = null; }

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Reminder current = reminder;
		if (current == null || !config.enabled() || !config.showFeedback()
			|| client.getGameState() != GameState.LOGGED_IN
			|| clock.getAsLong() - current.startedAt >= DURATION_NANOS)
		{
			return null;
		}
		panelComponent.getChildren().add(LineComponent.builder().left(current.tab).build());
		panelComponent.getChildren().add(LineComponent.builder().left("Use your tab keybind").build());
		return super.render(graphics);
	}

	private static final class Reminder
	{
		private final String tab;
		private final long startedAt;

		private Reminder(String tab, long startedAt)
		{
			this.tab = tab;
			this.startedAt = startedAt;
		}
	}
}

package com.fkeytrainer;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "F-Key Trainer",
	description = "Train keyboard tab switching by blocking mouse actions on selected tabs",
	tags = {"fkeys", "keyboard", "tabs", "training"}
)
public class FKeyTrainerPlugin extends Plugin
{
	@Inject Client client;
	@Inject FKeyTrainerConfig config;
	@Inject OverlayManager overlayManager;
	@Inject FKeyTrainerOverlay overlay;
	private volatile boolean active;

	@Provides
	FKeyTrainerConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(FKeyTrainerConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlay.clear();
		overlayManager.add(overlay);
		active = true;
	}

	@Override
	protected void shutDown()
	{
		active = false;
		overlayManager.remove(overlay);
		overlay.clear();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!active || !config.enabled() || event.isConsumed()
			|| client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		// Native tab buttons use static CC_OP entries. Do not match menu text,
		// RUNELITE options, item actions, dynamic children, or unknown operations.
		MenuAction action = event.getMenuAction();
		if ((action != MenuAction.CC_OP && action != MenuAction.CC_OP_LOW_PRIORITY)
			|| event.getParam0() != -1 || event.getId() < 1 || event.getId() > 10)
		{
			return;
		}

		GameTab tab = GameTab.fromWidget(client.getTopLevelInterfaceId(), event.getParam1());
		if (tab == null || !tab.isBlocked(config))
		{
			return;
		}
		Widget widget = client.getWidget(event.getParam1());
		if (widget == null || widget.isHidden())
		{
			return;
		}

		// The game's on-key script calls toplevel_sidebutton_op directly; it
		// does not dispatch this menu event. Never intercept scripts or keys.
		event.consume();
		if (config.showFeedback())
		{
			overlay.show(tab);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (FKeyTrainerConfig.GROUP.equals(event.getGroup())) { overlay.clear(); }
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN) { overlay.clear(); }
	}
}

package com.fkeytrainer;

import java.util.function.Predicate;
import net.runelite.api.gameval.InterfaceID;

/** Explicit allowlist of native tab buttons, not tab contents or decorative icons. */
enum GameTab
{
	COMBAT("Combat Options", FKeyTrainerConfig::blockCombat,
		InterfaceID.Toplevel.STONE0, InterfaceID.ToplevelOsrsStretch.STONE0, InterfaceID.ToplevelPreEoc.STONE0),
	SKILLS("Skills", FKeyTrainerConfig::blockSkills,
		InterfaceID.Toplevel.STONE1, InterfaceID.ToplevelOsrsStretch.STONE1, InterfaceID.ToplevelPreEoc.STONE1),
	QUESTS("Quests / Journal", FKeyTrainerConfig::blockQuests,
		InterfaceID.Toplevel.STONE2, InterfaceID.ToplevelOsrsStretch.STONE2, InterfaceID.ToplevelPreEoc.STONE2),
	INVENTORY("Inventory", FKeyTrainerConfig::blockInventory,
		InterfaceID.Toplevel.STONE3, InterfaceID.ToplevelOsrsStretch.STONE3, InterfaceID.ToplevelPreEoc.STONE3),
	EQUIPMENT("Worn Equipment", FKeyTrainerConfig::blockEquipment,
		InterfaceID.Toplevel.STONE4, InterfaceID.ToplevelOsrsStretch.STONE4, InterfaceID.ToplevelPreEoc.STONE4),
	PRAYER("Prayer", FKeyTrainerConfig::blockPrayer,
		InterfaceID.Toplevel.STONE5, InterfaceID.ToplevelOsrsStretch.STONE5, InterfaceID.ToplevelPreEoc.STONE5),
	MAGIC("Magic", FKeyTrainerConfig::blockMagic,
		InterfaceID.Toplevel.STONE6, InterfaceID.ToplevelOsrsStretch.STONE6, InterfaceID.ToplevelPreEoc.STONE6),
	CHANNELS("Chat Channels", FKeyTrainerConfig::blockChannels,
		InterfaceID.Toplevel.STONE7, InterfaceID.ToplevelOsrsStretch.STONE7, InterfaceID.ToplevelPreEoc.STONE7),
	ACCOUNT("Account Management", FKeyTrainerConfig::blockAccount,
		InterfaceID.Toplevel.STONE8, InterfaceID.ToplevelOsrsStretch.STONE8, InterfaceID.ToplevelPreEoc.STONE8),
	FRIENDS("Friends / Ignore", FKeyTrainerConfig::blockFriends,
		InterfaceID.Toplevel.STONE9, InterfaceID.ToplevelOsrsStretch.STONE9, InterfaceID.ToplevelPreEoc.STONE9),
	LOGOUT("Logout", FKeyTrainerConfig::blockLogout,
		InterfaceID.Toplevel.STONE10, InterfaceID.ToplevelOsrsStretch.STONE10, InterfaceID.ToplevelPreEoc.STONE10),
	SETTINGS("Settings", FKeyTrainerConfig::blockSettings,
		InterfaceID.Toplevel.STONE11, InterfaceID.ToplevelOsrsStretch.STONE11, InterfaceID.ToplevelPreEoc.STONE11),
	EMOTES("Emotes", FKeyTrainerConfig::blockEmotes,
		InterfaceID.Toplevel.STONE12, InterfaceID.ToplevelOsrsStretch.STONE12, InterfaceID.ToplevelPreEoc.STONE12),
	MUSIC("Music", FKeyTrainerConfig::blockMusic,
		InterfaceID.Toplevel.STONE13, InterfaceID.ToplevelOsrsStretch.STONE13, InterfaceID.ToplevelPreEoc.STONE13);

	private final String displayName;
	private final Predicate<FKeyTrainerConfig> blocked;
	private final int fixed;
	private final int classic;
	private final int modern;

	GameTab(String displayName, Predicate<FKeyTrainerConfig> blocked, int fixed, int classic, int modern)
	{
		this.displayName = displayName;
		this.blocked = blocked;
		this.fixed = fixed;
		this.classic = classic;
		this.modern = modern;
	}

	String displayName() { return displayName; }
	boolean isBlocked(FKeyTrainerConfig config) { return blocked.test(config); }

	int widgetId(int root)
	{
		switch (root)
		{
			case InterfaceID.TOPLEVEL: return fixed;
			case InterfaceID.TOPLEVEL_OSRS_STRETCH: return classic;
			case InterfaceID.TOPLEVEL_PRE_EOC: return modern;
			default: return -1;
		}
	}

	static GameTab fromWidget(int root, int widgetId)
	{
		if (widgetId < 0) { return null; }
		for (GameTab tab : values())
		{
			if (tab.widgetId(root) == widgetId) { return tab; }
		}
		return null;
	}
}

